sealed interface Node { val children: List<Node> }

data class IntLit(val value: Int) : Node {
    override val children: List<Node> = emptyList()
}
data class Add(val left: Node, val right: Node) : Node {
    override val children: List<Node> = listOf(left, right)
}

fun walk(n: Node, visit: (Node) -> Unit) {
    visit(n)
    n.children.forEach { walk(it, visit) }
}
